userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="btnPlay">▶ Play mapping</button>
<label>
  <span>Interpolation t</span>
  <input id="tSlider" type="range" min="0" max="1" step="0.01" value="0">
  <span id="tReadout">t = 0.00</span>
</label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ELEMENT SPEC (one comment per visible element — built exactly as specced)
//  lower plane   → 4 heavy edge cylinders, #44474d, r=0.035, corners (±3, 0, ±3)
//  upper plane   → 4 heavy edge cylinders, #44474d, r=0.035, corners (±3, 6, ±3)
//  axis crosses  → LineSegments #cccccc through each plane center (X and Z)
//  frame         → merged dashed LineSegments #999999, 4 verticals corner→corner
//  trajectories  → ONE merged dashed LineSegments #e03333, ~55 paths, opacity 0.45
//  cloud dots    → InstancedMesh(SphereGeometry 0.07), red lerp #dd2222→#ff5555 (all 150, driven by t)
//  segment bar   → thick solid cylinder #dd2222, r=0.09, along X at z=-2.2 on upper plane
//  segment dots  → ~11 static red spheres (r=0.09) packed along the bar
//  gray arrow    → 1 slim cylinder + 2 small cones #999999, ±X, exactly over the segment
//  pick planes   → two invisible PlaneGeometry meshes for hover explanation
const PLANE_HALF = 3, IN_Y = 0, OUT_Y = 6;
const SEG_Z = -2.2, SEG_HALF = 1.2, TANH_SCALE = 1.5;
const N = 150, N_TRAJ = 55, SIGMA = 1.2;

// deterministic RNG (mulberry32) + Box–Muller gaussian
let _seed = 0x9e3779b9;
function rng() {
  _seed = (_seed + 0x6D2B79F5) | 0;
  let t = Math.imul(_seed ^ (_seed >>> 15), 1 | _seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function gauss(s) {
  let u = 0; while (u === 0) u = rng();
  return s * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rng());
}

function cylinderBetween(a, b, r, color) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 12),
    new THREE.MeshBasicMaterial({ color }));
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return mesh;
}
function dashedSegments(flatPairs, color, dashSize, gapSize, opacity = 1) {
  const pos = [], dist = [];
  for (let i = 0; i < flatPairs.length; i += 2) {
    const a = flatPairs[i], b = flatPairs[i + 1];
    pos.push(a.x, a.y, a.z, b.x, b.y, b.z);
    dist.push(0, a.distanceTo(b));
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('lineDistance', new THREE.Float32BufferAttribute(dist, 1));
  return new THREE.LineSegments(g, new THREE.LineDashedMaterial({
    color, dashSize, gapSize, transparent: true, opacity
  }));
}

// ── planes: heavy edges + faint crosses ──────────────────────────────
const CORNERS = [[-PLANE_HALF, -PLANE_HALF], [PLANE_HALF, -PLANE_HALF],
[PLANE_HALF, PLANE_HALF], [-PLANE_HALF, PLANE_HALF]];
for (const y of [IN_Y, OUT_Y]) {
  for (let i = 0; i < 4; i++) {
    const a = CORNERS[i], b = CORNERS[(i + 1) % 4];
    scene.add(cylinderBetween(new THREE.Vector3(a[0], y, a[1]),
      new THREE.Vector3(b[0], y, b[1]), 0.035, 0x44474d));
  }
  const cross = [
    new THREE.Vector3(-PLANE_HALF, y, 0), new THREE.Vector3(PLANE_HALF, y, 0),
    new THREE.Vector3(0, y, -PLANE_HALF), new THREE.Vector3(0, y, PLANE_HALF)];
  scene.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(cross),
    new THREE.LineBasicMaterial({ color: 0xcccccc })));
}

// ── frame: four dashed verticals at the corners ──────────────────────
const framePairs = [];
for (const c of CORNERS) {
  framePairs.push(new THREE.Vector3(c[0], IN_Y, c[1]), new THREE.Vector3(c[0], OUT_Y, c[1]));
}
scene.add(dashedSegments(framePairs, 0x999999, 0.3, 0.22, 0.8));

// ── sample the input cloud, define the mapping ───────────────────────
const inPos = [], outPos = [];
for (let i = 0; i < N; i++) {
  let x = 0, z = 0, tries = 0;
  do { x = gauss(SIGMA); z = gauss(SIGMA); tries++; }
  while ((Math.abs(x) > 2.9 || Math.abs(z) > 2.9) && tries < 60);
  inPos.push(new THREE.Vector3(x, IN_Y, z));
  outPos.push(new THREE.Vector3(SEG_HALF * Math.tanh(x / TANH_SCALE), OUT_Y, SEG_Z));
}

// ── trajectories: only ~55 distinct dashed paths, light opacity ─────
const SEGMENTS_PER_PATH = 36;
const trajPts = [];
const trajIdx = new Set();
while (trajIdx.size < N_TRAJ) trajIdx.add(Math.floor(rng() * N));
for (const i of trajIdx) {
  const a = inPos[i], b = outPos[i];
  const p0 = new THREE.Vector3(), p1 = new THREE.Vector3();
  for (let s = 0; s < SEGMENTS_PER_PATH; s++) {
    p0.lerpVectors(a, b, s / SEGMENTS_PER_PATH);
    p1.lerpVectors(a, b, (s + 1) / SEGMENTS_PER_PATH);
    trajPts.push(p0.clone(), p1.clone());
  }
}
scene.add(dashedSegments(trajPts, 0xe03333, 0.22, 0.16, 0.45));

// ── endpoint dots at BOTH termini (static resting state, like source) ─
const endDotMat = new THREE.MeshBasicMaterial({ color: 0xee3333 });
const endDotGeo = new THREE.SphereGeometry(0.07, 10, 10);
for (const i of trajIdx) {
  const dIn = new THREE.Mesh(endDotGeo, endDotMat);
  dIn.position.copy(inPos[i]);
  scene.add(dIn);
  const dOut = new THREE.Mesh(endDotGeo, endDotMat);
  dOut.position.copy(outPos[i]);
  scene.add(dOut);
}

// ── thick solid red segment bar on the upper plane, red dots along it ──
const bar = cylinderBetween(new THREE.Vector3(-SEG_HALF, OUT_Y, SEG_Z),
  new THREE.Vector3(SEG_HALF, OUT_Y, SEG_Z), 0.075, 0xdd2222);
scene.add(bar);
const segDotGeo = new THREE.SphereGeometry(0.095, 12, 12);
const segDotMat = new THREE.MeshBasicMaterial({ color: 0xdd2222 });
const N_SEGDOTS = 11;
for (let k = 0; k < N_SEGDOTS; k++) {
  const dSeg = new THREE.Mesh(segDotGeo, segDotMat);
  dSeg.position.set(-SEG_HALF + (2 * SEG_HALF) * (k / (N_SEGDOTS - 1)), OUT_Y, SEG_Z);
  scene.add(dSeg);
}

// ── slim gray double-headed arrow exactly over the segment ──────────
scene.add(cylinderBetween(new THREE.Vector3(-2.15, OUT_Y, SEG_Z),
  new THREE.Vector3(2.15, OUT_Y, SEG_Z), 0.012, 0x999999));
for (const dirSign of [1, -1]) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.22, 12),
    new THREE.MeshBasicMaterial({ color: 0x999999 }));
  cone.rotation.z = dirSign > 0 ? -Math.PI / 2 : Math.PI / 2; // apex → ±X
  cone.position.set(dirSign * 2.26, OUT_Y, SEG_Z);
  scene.add(cone);
}

// ── cloud dots: ONE InstancedMesh, matrices updated from t ──────────
const dots = new THREE.InstancedMesh(
  new THREE.SphereGeometry(0.07, 12, 12),
  new THREE.MeshBasicMaterial(), N);
const colA = new THREE.Color(0xdd2222), colB = new THREE.Color(0xff5555);
const _m4 = new THREE.Matrix4(), _v3 = new THREE.Vector3();
for (let i = 0; i < N; i++) dots.setColorAt(i, colA.clone().lerp(colB, rng()));
dots.instanceColor.needsUpdate = true;
scene.add(dots);
function setDots(t) {
  for (let i = 0; i < N; i++) {
    _v3.lerpVectors(inPos[i], outPos[i], t);
    _m4.makeTranslation(_v3.x, _v3.y, _v3.z);
    dots.setMatrixAt(i, _m4);
  }
  dots.instanceMatrix.needsUpdate = true;
}
setDots(0);

// ── invisible pick planes for hover/click explanations ───────────────
function pickPlane(y, title, body) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(2 * PLANE_HALF, 2 * PLANE_HALF),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
  m.rotation.x = -Math.PI / 2;
  m.position.y = y;
  scene.add(m);
  registerInteractive(m, { title, body, tooltip: title });
}
pickPlane(IN_Y, 'Input: a 2D cloud',
  'Each red dot starts on this plane. The cloud is a 2D Gaussian — variation survives in both horizontal directions. Drag the slider (or press Play) to send every point upward.');
pickPlane(OUT_Y, 'Output: a 1D line',
  'All trajectories land packed onto one short segment near the back edge. The layer squeezes spread along one dimension — the second dimension of variation is lost.');
registerInteractive(dots, {
  title: 'Many inputs → one locus',
  body: 'Every point travels its own dashed path; because output x is squashed to ±1.2 at a fixed depth, many distinct inputs end up side by side on the same 1D segment.',
  tooltip: 'Many inputs → one locus'
});
registerInteractive(bar, {
  title: 'Collapsed segment',
  body: 'The output lives entirely on this short red bar: a one-dimensional locus on the upper plane. The gray arrowheads mark the only surviving direction of variation.',
  tooltip: 'Collapsed 1D segment'
});

// ── camera (after all geometry is in the scene) ──────────────────────
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: 0.65 });

// ── controls: Play mapping animation + interpolation slider ──────────
let tValue = 0, playing = false, playStart = 0;
const PLAY_MS = 4000;
const btnPlay = document.getElementById('btnPlay');
const slider = document.getElementById('tSlider');
const readout = document.getElementById('tReadout');
function applyT(t) {
  tValue = Math.min(1, Math.max(0, t));
  slider.value = tValue;
  readout.textContent = 't = ' + tValue.toFixed(2);
  setDots(tValue);
}
function easeInOut(u) { return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2; }
slider.addEventListener('input', () => {
  playing = false; btnPlay.textContent = '▶ Play mapping';
  applyT(parseFloat(slider.value));
});
btnPlay.addEventListener('click', () => {
  if (playing) { playing = false; btnPlay.textContent = '▶ Play mapping'; return; }
  if (tValue >= 1) applyT(0);           // loop: false — restart from input
  playing = true; playStart = performance.now();
  btnPlay.textContent = '⏸ Pause';
});
(function tick() {
  requestAnimationFrame(tick);
  if (!playing) return;
  const u = Math.min(1, (performance.now() - playStart) / PLAY_MS);
  applyT(easeInOut(u));
  if (u >= 1) { playing = false; btnPlay.textContent = '▶ Play mapping'; }
})();

// ── demo-step tween: goToStep(i) drives the same t as the slider ─────
const STEP_T = [0, 0.5, 1];
function tweenTo(target) {
  playing = false; btnPlay.textContent = '▶ Play mapping';
  const from = tValue, dT = target - from, start = performance.now(), MS = 900;
  (function stepTween() {
    const u = Math.min(1, (performance.now() - start) / MS);
    applyT(from + dT * easeInOut(u));
    if (u < 1) requestAnimationFrame(stepTween);
  })();
}
window.goToStep = function (i) {
  const idx = Math.max(0, Math.min(STEP_T.length - 1, i | 0));
  tweenTo(STEP_T[idx]);
};
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

